/* Local design prototype: fictitious suppliers, no business API or payment network. */
'use strict';
let previewRole='vendor',adminView='vendors',adminQuery='',adminStatus='all';
const INITIAL_VENDORS=Array.from({length:12},(_,i)=>({
 id:i+1,userId:2001+i,name:'演示供应商 '+String.fromCharCode(65+i),email:'vendor-'+String.fromCharCode(97+i)+'@example.invalid',
 status:i===1||i===8?'disabled':'active',platforms:['anthropic','openai'],groups:Object.values(GROUPS).flat(),
 accountLimit:50,proxyLimit:20,concurrency:5,priority:1,multiplier:1,direct:false,version:1,
 notes:i===1?'合作暂停':'演示合作资料',created:'2026-10-01',wechat:'演示联系人 '+String.fromCharCode(65+i),
 settlementEmail:'billing-'+String.fromCharCode(97+i)+'@example.invalid',binanceId:'DEMO-'+String(800000+i),coefficient:i%2?'1.6':'1.8'
}));
let vendors=structuredClone(INITIAL_VENDORS),adminEvents=[];
const INITIAL_EXTRA_ACCOUNTS=INITIAL_VENDORS.slice(1).flatMap(v=>[0,1].map(i=>({
 ...structuredClone(INITIAL_ACCOUNTS[i]),id:v.id*1000+i+1,vendorId:v.id,
 name:v.name+' · '+(i?'OpenAI 工作':'Claude 主力'),proxy:v.id*1000,
 credential:'DEMO_CREDENTIAL_VENDOR_'+v.id+'_'+i,created:'2026-10-01',paused:false,
 groups:i?['OpenAI 默认','OpenAI Coding']:['Claude 默认','Claude Coding'],archived:v.id===3&&i===1
})));
const INITIAL_EXTRA_PROXIES=INITIAL_VENDORS.slice(1).map(v=>({id:v.id*1000,vendorId:v.id,name:v.name+' 专属出口',host:'vendor-'+v.id+'.example.invalid',port:8080,protocol:'HTTP',state:'可用'}));
let extraAccounts=structuredClone(INITIAL_EXTRA_ACCOUNTS),extraProxies=structuredClone(INITIAL_EXTRA_PROXIES);
// A usage bucket has exactly one served group, irrespective of account memberships.
LEDGER.forEach((r,i)=>{r.id='A-'+i;r.vendor=1;r.group=INITIAL_ACCOUNTS.find(a=>a.id===r.account).groups[i%INITIAL_ACCOUNTS.find(a=>a.id===r.account).groups.length];});
let EXTRA_LEDGER=INITIAL_EXTRA_ACCOUNTS.flatMap(a=>LEDGER.filter(r=>r.account===(a.platform==='openai'?102:101)&&r.date>='2026-10-01').map((r,i)=>({...r,id:'V'+a.vendorId+'-'+a.id+'-'+i,account:a.id,vendor:a.vendorId,group:a.groups[i%a.groups.length],cost:Math.floor(r.cost*(50+a.vendorId*3)/100)})));
const defaultAdminFilters=()=>({vendor:'all',account:'all',platform:'all',group:'all',start:'2026-10-09',end:DEMO_TODAY,dimension:'vendor'});
let adminFilters=defaultAdminFilters(),adminPages={},adminError='';
const portalMode=new URLSearchParams(location.search).get('portal')==='vendor';
let portalLoggedIn=false;
let portalConfig={origin:'https://supplier.example.invalid',adminOrigin:'https://console.example.invalid'};
const requestedPortalOrigin=new URLSearchParams(location.search).get('origin');
if(requestedPortalOrigin){try{const u=new URL(requestedPortalOrigin);if(u.protocol==='https:'&&u.hostname.endsWith('.example.invalid')&&u.origin!==portalConfig.adminOrigin&&!u.port&&!u.username&&!u.password&&u.pathname==='/'&&!u.search&&!u.hash)portalConfig.origin=u.origin;}catch{}}
function ownerPolicy(){return vendors.find(v=>v.id===(window.vendorHierarchy?.actor.id||1))||vendors[0];}
function allAccounts(){return accounts.concat(extraAccounts);}
function allProxies(){return proxies.concat(extraProxies);}
function allLedger(){return LEDGER.concat(EXTRA_LEDGER);}
function findAccount(id){return allAccounts().find(a=>a.id===id);}
function accountVendor(a){return vendors.find(v=>v.id===(a.vendorId||1));}
function vendorAccounts(v){return allAccounts().filter(a=>(a.vendorId||1)===v.id);}
function vendorProxies(v){return allProxies().filter(p=>(p.vendorId||1)===v.id);}
function allowedGroups(platform){return GROUPS[platform].filter(g=>ownerPolicy().groups.includes(g));}
function vendorScopeBlock(a){const v=accountVendor(a),p=allProxies().find(p=>p.id===a.proxy);const exitBlock=p?(p.enabled===false?'代理停用':proxyExpired(p)?'代理过期':p.state==='异常'?'代理异常':''):a.proxy?'代理不存在':'';return v.status!=='active'?'供应商停用':exitBlock?exitBlock:!v.platforms.includes(a.platform)?'平台未开放':a.proxy===0&&!v.direct?'直连未授权':!a.groups.some(g=>v.groups.includes(g))?'分组未授权':'';}
function requireSuperAdmin(){if(!portalMode&&previewRole==='super_admin')return true;notify('无权限：只有超级管理员可以创建或管理供应商。');return false;}
function auditVendor(v,action,result){adminEvents.unshift({at:'2026-10-15 '+new Date().toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}),vendor:v.id,action,result});}
function actionButton(action,label,id,cls=''){return '<button class="'+cls+'" data-action="'+action+'" data-id="'+id+'">'+label+'</button>';}
function adminTable(headers,rows,label='后台数据'){return '<section class="panel"><div class="table-wrap"><table class="admin-table" aria-label="'+label+'"><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(cells=>'<tr>'+cells.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+(rows.length?'':'<tr><td colspan="'+headers.length+'" class="empty">此范围没有记录</td></tr>')+'</tbody></table></div></section>';}
function adminPage(rows){const key=adminView,p=adminPages[key]||1,max=Math.max(1,Math.ceil(rows.length/8));adminPages[key]=Math.min(p,max);return rows.slice((adminPages[key]-1)*8,adminPages[key]*8);}
function adminPager(count){const p=adminPages[adminView]||1,max=Math.max(1,Math.ceil(count/8));return '<div class="pagination"><span>共 '+count+' 条 · 每页 8 条</span><div class="row"><button data-action="admin-page" data-delta="-1" '+(p<=1?'disabled':'')+'>上一页</button><span>'+p+' / '+max+'</span><button data-action="admin-page" data-delta="1" '+(p>=max?'disabled':'')+'>下一页</button></div></div>';}
function options(items,value){return items.map(([id,label])=>'<option value="'+esc(id)+'" '+(String(id)===String(value)?'selected':'')+'>'+esc(label)+'</option>').join('');}
function adminSelect(key,label,items){return '<label>'+label+'<select data-admin-filter="'+key+'" aria-label="'+label+'">'+options(items,adminFilters[key])+'</select></label>';}
function adminFilterbar(dates=false){
 const available=allAccounts().filter(a=>adminFilters.vendor==='all'||(a.vendorId||1)===Number(adminFilters.vendor));
 return '<section class="panel admin-scope">'+adminSelect('vendor','供应商',[['all','全部供应商'],...vendors.map(v=>[v.id,v.name])])+adminSelect('account','账号',[['all','全部账号（含归档）'],...available.map(a=>[a.id,a.name+(a.archived?'（已归档）':'')])])+adminSelect('platform','平台',[['all','全部平台'],['anthropic','Anthropic'],['openai','OpenAI']])+adminSelect('group','计量分组',[['all','全部分组'],...Object.values(GROUPS).flat().map(g=>[g,g])])+(dates?'<label>开始日期<input type="date" id="admin-start" value="'+adminFilters.start+'" max="'+DEMO_TODAY+'"></label><label>结束日期<input type="date" id="admin-end" value="'+adminFilters.end+'" max="'+DEMO_TODAY+'"></label><button data-action="admin-dates">应用日期</button><button data-action="admin-range-all">全部历史</button>':'')+'<button data-action="admin-filter-reset">重置筛选</button><span class="muted small">Asia/Shanghai</span></section>'+(adminError?'<p class="form-error" role="alert">'+esc(adminError)+'</p>':'');
}
function adminRows(){return allLedger().filter(r=>r.date>=adminFilters.start&&r.date<=adminFilters.end&&(adminFilters.vendor==='all'||r.vendor===Number(adminFilters.vendor))&&(adminFilters.account==='all'||r.account===Number(adminFilters.account))&&(adminFilters.group==='all'||r.group===adminFilters.group)&&(adminFilters.platform==='all'||findAccount(r.account).platform===adminFilters.platform));}
function usageGroups(rows){const map=new Map();for(const r of rows){const key=adminFilters.dimension==='vendor'?String(r.vendor):adminFilters.dimension==='account'?String(r.account):adminFilters.dimension==='date'?r.date:adminFilters.dimension==='group'?r.group:r.account+'|'+r.date;if(!map.has(key))map.set(key,[]);map.get(key).push(r);}return [...map].map(([key,rs])=>({key,rows:rs,...total(rs)})).sort((a,b)=>adminFilters.dimension==='date'?a.key.localeCompare(b.key):b.cost-a.cost);}
function usageGroupLabel(g){const r=g.rows[0];if(adminFilters.dimension==='vendor')return actionButton('admin-drill-vendor',esc(vendors.find(v=>v.id===r.vendor).name),r.vendor,'text-button');if(adminFilters.dimension==='account'||adminFilters.dimension==='account-date'){const a=findAccount(r.account);return actionButton('admin-usage-detail',esc(a.name)+(a.archived?'（已归档）':''),a.id,'text-button')+'<small>'+esc(accountVendor(a).name)+(adminFilters.dimension==='account-date'?' · '+r.date:'')+'</small>';}return esc(g.key);}
function renderAdminUsage(){const rows=adminRows(),s=total(rows),groups=usageGroups(rows),reserved=new Set(settlements.filter(x=>x.state!=='void').flatMap(x=>x.rowIds)),assigned=rows.filter(r=>reserved.has(r.id));return adminFilterbar(true)+'<div class="plain-stats">'+[['统计消耗（USD）',money(s.cost)],['总请求数',number(s.requests)],['Token（含缓存）',number(s.input+s.output+s.write+s.read)],['未纳入结算消耗',money(s.cost-total(assigned).cost)]].map(([k,v])=>'<div class="panel">'+metric(k,v)+'</div>').join('')+'</div><div class="section-toolbar"><div class="segment" aria-label="用量聚合方式">'+[['vendor','按供应商'],['account','按账号'],['date','按日期'],['group','按分组'],['account-date','账号 × 日期']].map(([key,label])=>'<button data-action="admin-dimension" data-value="'+key+'" aria-pressed="'+(key===adminFilters.dimension)+'">'+label+'</button>').join('')+'</div><div class="row"><button data-action="admin-export-usage">导出当前明细 CSV</button><button class="primary" data-action="settlement-new">生成结算草稿</button></div></div>'+adminTable(['维度 / 归属','请求数','输入 / 输出 Token','缓存写入 / 读取','统计消耗（USD）'],adminPage(groups).map(g=>[usageGroupLabel(g),number(g.requests),usagePair(g),usagePair(g,true),money(g.cost)]),'供给用量明细')+adminPager(groups.length)+'<div class="notice">按请求实际服务分组计量，多选账号分组不会重复累计。包含已归档账号的历史。消费扣费、账号统计消耗、供应商应付金额分别核算；生成结算单后才能形成应付。</div>';}
function renderAdmin(){
 if(previewRole!=='super_admin'||portalMode){$('view').innerHTML=heading('供应商平台','后台权限预览')+'<section class="panel denied-panel"><span class="badge error">403 · 无访问权限</span><h2>仅超级管理员可管理供应商</h2><p>普通管理员可按原有权限创建 API Key、消费已获授权的共享分组；不能管理供应商身份、资源、结算或绕过旧接口权限。</p><p class="muted">此页面仅演示权限边界，未接入实际认证。</p></section>';return;}
 const list=vendors.filter(v=>(adminStatus==='all'||v.status===adminStatus)&&(v.name+' '+v.email+' '+v.wechat+' '+v.settlementEmail).toLowerCase().includes(adminQuery.toLowerCase()));
 const stats='<div class="plain-stats">'+[['供应商总数',vendors.length],['已启用',vendors.filter(v=>v.status==='active').length],['接入账号',allAccounts().filter(a=>!a.archived).length],['待付金额（USDT）',formatCents(settlements.filter(x=>['locked','partial'].includes(x.state)).reduce((s,x)=>s+x.amountCents-paidCents(x),0))]].map(([k,v])=>'<div class="panel">'+metric(k,v)+'</div>').join('')+'</div>';
 const tabs='<div class="admin-tabs" role="tablist" aria-label="供应商后台模块">'+[['vendors','供应商管理'],['accounts','供应商账号'],['proxies','供应商代理'],['usage','供给用量'],['settlements','结算对账'],['groups','分组供给'],['audit','操作审计']].map(([key,label])=>'<button role="tab" aria-selected="'+(adminView===key)+'" data-action="admin-tab" data-tab="'+key+'">'+label+'</button>').join('')+'</div>';
 let content='';
 if(adminView==='vendors')content='<div class="filterbar admin-filter"><input id="admin-search" aria-label="搜索供应商" placeholder="搜索供应商 / 登录邮箱 / 结算联系人" value="'+esc(adminQuery)+'"><select id="admin-status" aria-label="供应商状态">'+options([['all','全部状态'],['active','已启用'],['disabled','已停用']],adminStatus)+'</select><span class="muted small">仅超级管理员管理 · 收款资料脱敏展示</span></div>'+adminTable(['供应商 / 登录账号','状态','结算联系 / 收款资料','平台 / 允许分组','资源 / 上限','操作'],adminPage(list).map(v=>['<strong>'+esc(v.name)+'</strong><small>'+esc(v.email)+'</small><small>#V'+v.id+' · 用户 #'+v.userId+'</small>',badge(v.status==='active'?'已开通':'已停用'),esc(v.wechat)+'<small>'+esc(v.settlementEmail)+'</small><small>币安 ID ···'+esc(v.binanceId.slice(-4))+'</small>',v.platforms.map(platformName).join(' / ')+'<small>'+v.groups.map(esc).join('、')+'</small>','账号 '+vendorAccounts(v).length+'/'+v.accountLimit+'<small>代理 '+vendorProxies(v).length+'/'+v.proxyLimit+'</small>','<div class="row">'+actionButton('vendor-detail','详情',v.id)+actionButton('vendor-edit','配置',v.id)+actionButton('admin-drill-vendor','查用量',v.id)+actionButton('vendor-status',v.status==='active'?'停用':'启用',v.id,v.status==='active'?'danger':'')+'</div>']),'供应商管理列表')+adminPager(list.length);
 if(adminView==='accounts'){const rows=allAccounts().filter(a=>(adminFilters.vendor==='all'||(a.vendorId||1)===Number(adminFilters.vendor))&&(adminFilters.platform==='all'||a.platform===adminFilters.platform)&&(adminFilters.account==='all'||a.id===Number(adminFilters.account))&&(adminFilters.group==='all'||a.groups.includes(adminFilters.group)));content=adminFilterbar(true)+adminTable(['账号 / 归属','综合状态','授权分组','配额 / 重置时间','所选日期消耗','操作'],adminPage(rows).map(a=>[esc(a.name)+(a.archived?'<span class="badge archived">已归档</span>':'')+'<small>'+esc(accountVendor(a).name)+' · #'+a.id+'</small>',badge(status(a)),a.groups.map(esc).join('、'),'<div class="quota-cell">'+quotaCell(a)+'</div>',money(total(adminRows().filter(r=>r.account===a.id)).cost),'<div class="row">'+actionButton('detail','详情',a.id)+actionButton('admin-usage-detail','用量',a.id)+(accountAccess(a).manage?actionButton('admin-account-edit','编辑',a.id):'')+'</div>']),'供应商账号列表')+adminPager(rows.length);}
 if(adminView==='proxies')content=proxyWorkspace(true);
 if(adminView==='usage')content=renderAdminUsage();
 if(adminView==='settlements')content=renderSettlements();
 if(adminView==='groups')content=renderSupplyGroups();
 if(adminView==='audit'){const rows=adminEvents.filter(e=>adminFilters.vendor==='all'||e.vendor===Number(adminFilters.vendor));content='<section class="panel admin-scope">'+adminSelect('vendor','供应商',[['all','全部供应商'],...vendors.map(v=>[v.id,v.name])])+'</section>'+adminTable(['时间','操作者','供应商','操作','结果'],adminPage(rows).map(e=>[e.at,esc(e.actor||'超级管理员'),esc(vendors.find(v=>v.id===e.vendor)?.name||'系统'),esc(e.action),esc(e.result)]),'供应商操作审计')+adminPager(rows.length)+'<p class="muted small">结算状态、合同版本与付款登记均留痕；不记录凭证、完整收款资料或回调内容。</p>';}
 $('view').innerHTML=heading('供应商平台','超级管理员 / 合作供应商、资源供给与费用结算','<button data-action="portal-settings">独立入口设置</button>'+actionButton('vendor-create','＋ 创建供应商',0,'primary'))+stats+tabs+content;
 if(adminView==='proxies')renderProxyData();
}

function renderSupplyGroups(){return '<div class="notice">同一个系统分组可由平台账号及多个供应商共同供给。API Key 按所属用户的原有授权/订阅绑定分组；创建者为超级管理员、管理员或普通用户均可使用，不需要供应商管理权限。</div>'+adminTable(['系统原生分组','供给供应商','可用 / 全部账号','API Key 消费规则','操作'],Object.values(GROUPS).flat().map(g=>{const rows=allAccounts().filter(a=>!a.archived&&a.groups.includes(g));return [esc(g),new Set(rows.map(a=>a.vendorId||1)).size,rows.filter(a=>status(a)==='正常').length+' / '+rows.length,'复用用户分组授权 / 有效订阅', '<button data-action="group-preview" data-group="'+esc(g)+'">模拟 Key 访问</button>'];}),'共享分组供给')+'<div class="supply-flow"><span>三类用户创建 API Key</span><b>→</b><span>Key 所属用户的分组权限</span><b>→</b><span>原生分组 / 调度器</span><b>→</b><span>平台账号 + 多供应商账号</span></div><p class="muted small">不把 vendor_id 作为消费门槛；普通管理员仍不能查看供应商收款资料、授权凭证或结算单。</p>';}
function openGroupPreview(group){openModal('共享分组 · Key 访问模拟',group,'<div class="fieldgrid"><label>API Key 创建者<select id="key-role">'+options([['super_admin','超级管理员'],['admin','管理员'],['user','普通用户']],'user')+'</select></label><label>Key 所属用户的分组资格<select id="key-entitlement">'+options([['allowed','已获授权 / 有效订阅'],['denied','未获授权 / 订阅失效']],'allowed')+'</select></label></div><div id="key-access-result"></div>','<button data-action="group-preview-run" data-group="'+esc(group)+'">检查可用供给</button><button data-action="dismiss">关闭</button>');}
function openPortalSettings(){openModal('供应商独立入口','真实域名与部署需在正式实施时配置','<div class="notice">独立供应商子域名复用原用户认证服务；不开放自助注册，不暴露后台菜单。此处只演示配置和页面。</div><div class="fieldgrid"><label>供应商入口 Origin<input id="portal-origin" value="'+esc(portalConfig.origin)+'"></label><label>管理后台 Origin<input id="portal-admin-origin" value="'+esc(portalConfig.adminOrigin)+'" readonly></label></div>'+detailRows([['登录','仅超级管理员已开通的供应商；MFA / 会话复用原安全流程'],['会话隔离','复用现有 Token 会话；按 Origin 隔离浏览器存储，服务端复核角色与范围；如用 Cookie，限定 Host-only / Secure / HttpOnly'],['接口边界','供应商入口仅代理认证、本人资料及 /api/v1/vendor；后台接口拒绝'],['当前状态','仅本地原型，未配置 DNS、TLS 或生产登录']])+'<p id="portal-error" class="form-error"></p>','<a class="button-link" href="prototype.html?portal=vendor&amp;origin='+encodeURIComponent(portalConfig.origin)+'" target="_blank" rel="noopener">打开供应商独立入口原型 ↗</a><button data-action="portal-save">保存演示配置</button>');}
function renderPortalLogin(){
 document.querySelector('.sidebar').hidden=true;document.querySelector('.topbar').hidden=true;document.querySelector('.app').classList.add('portal-layout');
 $('view').innerHTML='<div class="portal-login"><div class="portal-brand"><span class="logo">S</span>供应商平台</div><span class="badge info">独立子域名登录 · 原型</span><h1>欢迎回到供应商工作区</h1><p>添加 Claude / OpenAI 账号，管理专属出口，查看自己的供给记录。</p><div class="portal-host">'+esc(portalConfig.origin)+'</div><label>登录邮箱<input id="portal-email" type="email" autocomplete="off" value="vendor-a@example.invalid"></label><p class="muted small">演示邮箱：vendor-a@example.invalid（一级）、vendor-b@example.invalid（二级）。不输入真实密码，不连接认证服务。</p><button class="primary" data-action="portal-login">进入演示供应商工作区</button><p id="portal-login-error" class="form-error"></p><p class="muted small">一级由超级管理员开通；二级由所属一级开通。无公开注册。</p></div>';
}
function resetAdminState(){extraAccounts=structuredClone(INITIAL_EXTRA_ACCOUNTS);extraProxies=structuredClone(INITIAL_EXTRA_PROXIES);adminFilters=defaultAdminFilters();adminPages={};adminError='';settlements=[];settlementSequence=0;settlementPreview=null;settlementFilter='all';draftScope=null;portalLoggedIn=false;}

let settlements=[],settlementSequence=0,settlementPreview=null,settlementFilter='all',draftScope=null;
const settlementLabels={draft:'草稿',locked:'待付款',partial:'部分付款',paid:'已付款',void:'已作废'};
function scaledDecimal(value,digits=6){const text=String(value).trim();if(!new RegExp('^-?\\d+(\\.\\d{1,'+digits+'})?$').test(text))throw new Error('金额与系数格式不正确');const negative=text[0]==='-',parts=text.replace('-','').split('.');return (negative?-1n:1n)*(BigInt(parts[0])*10n**BigInt(digits)+BigInt((parts[1]||'').padEnd(digits,'0')));}
function settlementCents(cost,coefficient,fx){const c=scaledDecimal(coefficient),f=scaledDecimal(fx);if(c<=0n||f<=0n||c>100000000000n||f>100000000000n)throw new Error('计价系数与换算价必须大于 0 且不超过 100000');const numerator=BigInt(cost)*c*100n,denominator=10000n*f;return Number((numerator+denominator/2n)/denominator);}
function formatCents(c){return (c/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
function paidCents(s){return s.payments.reduce((n,p)=>n+p.cents,0);}
function settlementBadge(state){return '<span class="badge '+({draft:'',locked:'warn',partial:'info',paid:'ok',void:''}[state])+'">'+settlementLabels[state]+'</span>';}
function statementLines(rows,coefficient,fx,groupCoefficients={}){return aggregate(rows,'group').map(g=>({...g,coefficient:groupCoefficients[g.id]||coefficient,amountCents:settlementCents(g.cost,groupCoefficients[g.id]||coefficient,fx)}));}
function makeStatement(v,rows,start,end,fx,coefficient,adjustment=0,reason='',groupCoefficients=v.groupCoefficients||{}){const lines=statementLines(rows,coefficient,fx,groupCoefficients);return {id:++settlementSequence,number:'VS-20261015-'+String(settlementSequence).padStart(3,'0'),vendor:v.id,vendorName:v.name,start,end,fx,coefficient,groupCoefficients:structuredClone(groupCoefficients),adjustment,reason,lines,base:total(rows).cost,amountCents:lines.reduce((n,g)=>n+g.amountCents,0)+adjustment,accountNames:Object.fromEntries(rows.map(r=>[r.account,findAccount(r.account).name])),rowIds:rows.map(r=>r.id),rows:structuredClone(rows),state:'draft',policyVersion:v.version,payee:{wechat:v.wechat,email:v.settlementEmail,binanceId:v.binanceId},payments:[],created:DEMO_NOW,scope:structuredClone(draftScope||{account:'all',group:'all',platform:'all'}),snapshotAt:DEMO_NOW};}
function renderSettlements(){
 const rows=settlements.filter(s=>(adminFilters.vendor==='all'||s.vendor===Number(adminFilters.vendor))&&(settlementFilter==='all'||s.state===settlementFilter)).sort((a,b)=>b.id-a.id);
 return '<div class="notice">结算消耗取自请求发生时的供应商归属与计量分组。草稿占用选中记录；确认后锁定金额、收款资料和系数。付款只登记线下结果，不会自动转账。</div><div class="section-toolbar"><div class="admin-scope">'+adminSelect('vendor','供应商',[['all','全部供应商'],...vendors.map(v=>[v.id,v.name])])+'<label>结算状态<select id="settlement-state">'+options([['all','全部状态'],...Object.entries(settlementLabels)],settlementFilter)+'</select></label></div><button class="primary" data-action="settlement-new">新建结算草稿</button></div>'+adminTable(['结算单 / 周期','供应商','基础消耗（USD）','应付 / 已付（USDT）','状态','操作'],adminPage(rows).map(s=>['<strong>'+s.number+'</strong><small>'+s.start+' — '+s.end+'</small>',esc(s.vendorName),money(s.base),'<strong>'+formatCents(s.amountCents)+'</strong><small>已付 '+formatCents(paidCents(s))+' · 剩余 '+formatCents(Math.max(0,s.amountCents-paidCents(s)))+'</small>',settlementBadge(s.state),'<div class="row">'+actionButton('statement-detail','查看',s.id)+(s.state==='draft'?actionButton('statement-detail','确认锁账',s.id):'')+(['locked','partial'].includes(s.state)?actionButton('payment-open','登记付款',s.id):'')+'</div>']),'供应商结算单')+adminPager(rows.length)+'<section class="panel formula-example"><h3>截图公式示例 · 不计入账单</h3><p>为明确截图单位，暂按“计价系数 CNY / 消耗 USD、换算价 CNY / USDT”演示，正式合同需确认此定义。</p><div class="formula-row"><span>6,994.09 × 1.8 ÷ 6.7</span><strong>'+formatCents(settlementCents(69940900,'1.8','6.7'))+' USDT</strong></div><div class="formula-row"><span>2,036.31 × 1.6 ÷ 6.7</span><strong>'+formatCents(settlementCents(20363100,'1.6','6.7'))+' USDT</strong></div><div class="formula-row"><span>两笔合计</span><strong>'+formatCents(settlementCents(69940900,'1.8','6.7')+settlementCents(20363100,'1.6','6.7'))+' USDT</strong></div><small>这里不是实时 USDT 市价；账号统计倍率与合同计价系数是两个字段，不重复乘账号倍率。</small></section>';
}
function openSettlementDraft(){
 if(!requireSuperAdmin())return;draftScope=structuredClone(adminFilters);settlementPreview=null;
 openModal('生成结算草稿','选择供应商与账期，先预览再保存。全部金额仅为演示。','<div class="notice">已被其他有效结算单占用的用量记录自动排除。可批量生成多供应商草稿；默认取已闭合日期。当前筛选：'+esc(adminFilters.account==='all'?'全部账号':findAccount(Number(adminFilters.account)).name)+' / '+esc(adminFilters.group==='all'?'全部计量分组':adminFilters.group)+'</div><div class="fieldgrid"><label>结算供应商<select id="settle-vendor" data-settlement-input>'+options([['all','全部供应商（逐家生成）'],...vendors.map(v=>[v.id,v.name])],adminFilters.vendor)+'</select></label><label>USDT 换算价（CNY / USDT）<input id="settle-fx" data-settlement-input type="number" min="0.000001" step="0.000001" value="6.7"></label><label>账期开始<input id="settle-start" data-settlement-input type="date" value="'+adminFilters.start+'" max="'+DEMO_TODAY+'"></label><label>账期结束<input id="settle-end" data-settlement-input type="date" value="'+(adminFilters.end===DEMO_TODAY?addDays(DEMO_TODAY,-1):adminFilters.end)+'" max="'+DEMO_TODAY+'"></label><label>调整金额（USDT，仅单供应商）<input id="settle-adjustment" data-settlement-input type="number" step="0.01" value="0"></label><label>调整原因<input id="settle-reason" data-settlement-input maxlength="200" placeholder="有调整时必填"></label></div><p class="muted small">每家供应商按结算档案使用默认系数或分组覆盖系数（CNY / 消耗 USD）。汇率、系数及收款资料随结算单固化。按分组行四舍五入至 0.01 USDT 后求和。</p><p id="settlement-error" class="form-error" role="alert"></p><div id="settlement-preview"></div>','<button data-action="dismiss">取消</button><button data-action="settlement-preview">预览金额</button><button class="primary" id="settlement-save" data-action="settlement-save" disabled>保存草稿</button>');$('modal').classList.add('wide');
}
function previewSettlement(){
 try{
 const start=$('settle-start').value,end=$('settle-end').value,vendor=$('settle-vendor').value,fx=$('settle-fx').value,reason=$('settle-reason').value.trim(),adjustment=Number(scaledDecimal($('settle-adjustment').value,2));
 if(!start||!end||start>end||end>DEMO_TODAY)throw new Error('请选择有效账期，结束不能晚于演示今日。');
 if(adjustment&&(!reason||vendor==='all'))throw new Error('调整金额需要选择单个供应商并填写原因。');
 const reserved=new Set(settlements.filter(s=>s.state!=='void').flatMap(s=>s.rowIds));
 const relevant=allLedger().filter(r=>r.date>=start&&r.date<=end&&(vendor==='all'||r.vendor===Number(vendor))&&(draftScope.account==='all'||r.account===Number(draftScope.account))&&(draftScope.group==='all'||r.group===draftScope.group)&&(draftScope.platform==='all'||findAccount(r.account).platform===draftScope.platform));
 const free=relevant.filter(r=>!reserved.has(r.id));const chosen=vendors.filter(v=>free.some(r=>r.vendor===v.id));
 if(!chosen.length)throw new Error('没有可结算记录：本范围无用量或已全部纳入有效结算单。');
 const result=chosen.map(v=>{if(!v.settlementEmail||!v.binanceId||!v.wechat)throw new Error(v.name+' 的结算资料不完整');const rows=free.filter(r=>r.vendor===v.id),lines=statementLines(rows,v.coefficient,fx,v.groupCoefficients),amount=lines.reduce((n,g)=>n+g.amountCents,0)+adjustment;if(amount<=0)throw new Error('应付金额必须大于 0，请检查调整金额');return {v,rows,start,end,fx,coefficient:v.coefficient,groupCoefficients:structuredClone(v.groupCoefficients||{}),adjustment,reason,amount};});
 settlementPreview=result;$('settlement-error').textContent='';$('settlement-preview').innerHTML='<div class="notice">将生成 '+result.length+' 份草稿 · 跳过已占用 '+(relevant.length-free.length)+' 条用量记录'+(end===DEMO_TODAY?' · 今日未闭合，草稿不可确认锁账':'')+'</div>'+adminTable(['供应商','消耗 USD','计价系数 CNY/USD','换算价 CNY/USDT','应付 USDT'],result.map(x=>[esc(x.v.name),money(total(x.rows).cost),esc(x.coefficient)+(Object.keys(x.groupCoefficients).length?'（含分组覆盖）':''),esc(x.fx),formatCents(x.amount)]),'结算预览');$('settlement-save').disabled=false;$('settlement-save').textContent='保存 '+result.length+' 份草稿';
 }catch(error){settlementPreview=null;$('settlement-error').textContent=error.message;$('settlement-preview').innerHTML='';$('settlement-save').disabled=true;}
}
function saveSettlementDraft(){if(!requireSuperAdmin()||!settlementPreview)return;const reserved=new Set(settlements.filter(s=>s.state!=='void').flatMap(s=>s.rowIds));if(settlementPreview.some(x=>x.rows.some(r=>reserved.has(r.id)))){$('settlement-error').textContent='用量占用已变化，请重新预览。';return;}for(const x of settlementPreview){const s=makeStatement(x.v,x.rows,x.start,x.end,x.fx,x.coefficient,x.adjustment,x.reason,x.groupCoefficients);settlements.push(s);auditVendor(x.v,'创建结算草稿',s.number+' · '+formatCents(s.amountCents)+' USDT');}const count=settlementPreview.length;settlementPreview=null;$('modal').close();adminView='settlements';adminPages.settlements=1;settlementFilter='all';renderAdmin();notify('已生成 '+count+' 份演示草稿，未执行付款。');}
function statementDetail(id){const s=settlements.find(x=>x.id===id);if(!s||(previewRole!=='super_admin'&&(previewRole!=='vendor'||s.vendor!==1||!['locked','partial','paid'].includes(s.state))))return;const manage=previewRole==='super_admin'&&!portalMode;
 openModal(s.number+' · 结算单',s.vendorName+' · '+s.start+' — '+s.end+' · Asia/Shanghai','<div class="statement-status">'+settlementBadge(s.state)+'<strong>应付 '+formatCents(s.amountCents)+' USDT</strong><span>已付 '+formatCents(paidCents(s))+' · 剩余 '+formatCents(s.amountCents-paidCents(s))+'</span></div>'+detailRows([['计量口径','账号统计消耗 USD，已包含历史账号统计倍率'],['计算规则','分组消耗 USD × 各组系数 CNY/USD ÷ '+esc(s.fx)+' CNY/USDT；每组取两位小数后求和'],['收款档案快照',esc(s.payee.wechat)+' · '+esc(s.payee.email)+' · 币安 '+esc(s.payee.binanceId)],['策略 / 数据快照','v'+s.policyVersion+' · '+s.snapshotAt],['调整',formatCents(s.adjustment)+' USDT · '+esc(s.reason||'无调整')]])+adminTable(['实际计量分组','请求','消耗（USD）','系数（CNY/USD）','应付（USDT）'],s.lines.map(g=>[esc(g.id),number(g.requests),money(g.cost),esc(g.coefficient),formatCents(g.amountCents)]),'结算分组明细')+'<div class="section-toolbar"><h3>付款记录</h3><span class="muted small">站外支付结果登记，不触发转账</span></div>'+adminTable(['日期','凭据编号','登记金额（USDT）'],s.payments.map(p=>[p.date,esc(p.reference),formatCents(p.cents)]),'结算付款记录')+'<div class="notice">账号删除、分组调整、结算档案或倍率修改均不改写本单。已付款单不直接修改或作废，差异应通过有依据的调整单处理。</div>'+(s.end===DEMO_TODAY&&s.state==='draft'?'<p class="form-error">账期尚未闭合，不可确认锁账。</p>':'')+'<p id="statement-error" class="form-error"></p>',
 '<div class="row">'+actionButton('statement-export','导出账单明细',s.id)+(manage&&['draft','locked'].includes(s.state)?actionButton('statement-void-open','作废',s.id,'danger'):'')+'</div><div class="buttons">'+(manage&&s.state==='draft'&&s.end<DEMO_TODAY?actionButton('statement-lock','确认并锁定金额',s.id,'primary'):'')+(manage&&['locked','partial'].includes(s.state)?actionButton('payment-open','登记付款',s.id,'primary'):'')+actionButton('dismiss','关闭',0)+'</div>');$('modal').classList.add('wide');
}
function openPayment(id){if(!requireSuperAdmin())return;const s=settlements.find(x=>x.id===id);if(!s||!['locked','partial'].includes(s.state))return;openModal('登记线下付款',s.number+' · '+s.vendorName,'<div class="notice">此操作只登记已发生的线下付款，不连接币安、不发送资金。剩余应付 '+formatCents(s.amountCents-paidCents(s))+' USDT。</div><div class="fieldgrid"><label>付款金额（USDT）<input id="payment-amount" type="number" step="0.01" min="0.01" value="'+((s.amountCents-paidCents(s))/100).toFixed(2)+'"></label><label>付款日期<input id="payment-date" type="date" max="'+DEMO_TODAY+'" value="'+DEMO_TODAY+'"></label><label class="wide">付款凭据编号<input id="payment-reference" maxlength="100" placeholder="DEMO-PAY-001（原型仅填虚构编号）"></label></div><label class="checkline"><input type="checkbox" id="payment-confirm">确认已在线下付款，并核对本单收款档案</label><p id="payment-error" class="form-error" role="alert"></p>','<button data-action="dismiss">取消</button>'+actionButton('payment-save','登记付款（仅记录）',id,'primary'));}
function savePayment(id){if(!requireSuperAdmin())return;const s=settlements.find(x=>x.id===id);try{if(!s||!['locked','partial'].includes(s.state))throw new Error('账单状态已变化');const cents=Number(scaledDecimal($('payment-amount').value,2)),date=$('payment-date').value,reference=$('payment-reference').value.trim();if(!$('payment-confirm').checked)throw new Error('请确认线下付款事实');if(cents<=0||cents>s.amountCents-paidCents(s))throw new Error('付款金额须大于 0 且不超过剩余应付');if(!date||date>DEMO_TODAY)throw new Error('付款日期不能晚于演示今日');if(!/^DEMO-[A-Za-z0-9-]+$/.test(reference))throw new Error('原型仅接受 DEMO- 开头的虚构凭据编号');if(settlements.some(x=>x.payments.some(p=>p.reference===reference)))throw new Error('该付款凭据已登记，请勿重复提交');s.payments.push({cents,date,reference});s.state=paidCents(s)===s.amountCents?'paid':'partial';auditVendor(vendors.find(v=>v.id===s.vendor),'登记线下付款',s.number+' · '+formatCents(cents)+' USDT · '+settlementLabels[s.state]);renderAdmin();statementDetail(id);}catch(error){$('payment-error').textContent=error.message;}}
function csvDownload(name,headers,rows){const cell=value=>'"'+String(value??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const text='\ufeff'+[headers,...rows].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportAdminUsage(){if(!requireSuperAdmin())return;const rows=adminRows();csvDownload('supplier-usage-'+adminFilters.start+'-'+adminFilters.end+'.csv',['数据性质','供应商ID','供应商','账号ID','账号','账号状态','请求日期','实际计量分组','请求数','输入Token','输出Token','缓存写','缓存读','账号统计消耗USD','统计时区'],rows.map(r=>['DEMO',r.vendor,vendors.find(v=>v.id===r.vendor).name,r.account,findAccount(r.account).name,findAccount(r.account).archived?'已归档':'有效',r.date,r.group,r.requests,r.input,r.output,r.write,r.read,(r.cost/10000).toFixed(4),'Asia/Shanghai']));notify('已导出当前筛选的全部明细（不受分页影响），没有凭证或消费者身份。');}
function exportStatement(id){
 const s=settlements.find(x=>x.id===id);if(!s||(previewRole!=='super_admin'&&(previewRole!=='vendor'||s.vendor!==1||!['locked','partial','paid'].includes(s.state))))return;
 const groups=new Map();for(const r of s.rows){const key=r.account+'|'+r.date+'|'+r.group;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}
 const prefix=[s.number,s.vendorName,s.start,s.end];
 const output=[...groups.values()].map(rows=>{const r=rows[0];return ['用量明细',...prefix,r.account,s.accountNames[r.account],r.date,r.group,total(rows).requests,(total(rows).cost/10000).toFixed(4),s.lines.find(g=>g.id===r.group).coefficient,s.fx,'','','','',s.snapshotAt];});
 for(const g of s.lines)output.push(['分组结算',...prefix,'','','',g.id,'','',g.coefficient,s.fx,(g.amountCents/100).toFixed(2),'','','',s.snapshotAt]);
 const summary=Array(18).fill('');summary.splice(0,5,'本单合计',...prefix);summary[14]=(s.adjustment/100).toFixed(2);summary[15]=(s.amountCents/100).toFixed(2);summary[16]=(paidCents(s)/100).toFixed(2);summary[17]=s.snapshotAt;output.push(summary);
 csvDownload(s.number+'-demo.csv',['记录类型','结算单','供应商','账期开始','账期结束','账号ID','账号快照名称','请求日期','计量分组','请求数','明细消耗USD','计价系数CNY/USD','换算价CNY/USDT','分组应付USDT','调整USDT','本单应付USDT','本单已付USDT','数据快照'],output);
 notify('已导出快照明细、分组结算行与独立合计行，账单总额不重复铺入明细。');
}

function renderVendorSettlements(){const rows=settlements.filter(s=>s.vendor===1&&['locked','partial','paid'].includes(s.state));$('view').innerHTML=heading('我的结算','仅自己的已确认账单 · 付款状态以平台登记为准')+adminTable(['结算单 / 周期','应付 USDT','已付 USDT','状态','操作'],rows.map(s=>[s.number+'<small>'+s.start+' — '+s.end+'</small>',formatCents(s.amountCents),formatCents(paidCents(s)),settlementBadge(s.state),actionButton('statement-detail','查看明细',s.id)]),'我的结算单')+'<div class="notice">存在金额或收款资料差异时联系超级管理员；供应商不能改动合同规则、锁账金额或付款记录。</div>';}
function seedStatements(){for(const [index,v] of vendors.slice(0,3).entries()){const rows=allLedger().filter(r=>r.vendor===v.id&&r.date>='2026-10-01'&&r.date<='2026-10-07');const s=makeStatement(v,rows,'2026-10-01','2026-10-07','6.7',v.coefficient);s.state=index===0?'locked':index===1?'partial':'paid';if(index)s.payments.push({cents:index===1?Math.floor(s.amountCents/2):s.amountCents,date:'2026-10-12',reference:'DEMO-INITIAL-'+index});settlements.push(s);}adminEvents=[{at:'2026-10-15 12:00',vendor:1,action:'确认演示结算单',result:settlements[0].number+' · 收款资料及金额已锁定'}];}

function groupCoefficientFields(v){return '<details class="form-section"><summary>分组计价系数（选填，留空使用默认）</summary><div class="fieldgrid">'+Object.values(GROUPS).flat().map(g=>'<label>'+esc(g)+'<input data-group-coefficient="'+esc(g)+'" type="number" min="0.000001" step="0.000001" value="'+esc(v.groupCoefficients?.[g]||'')+'" placeholder="使用默认系数"></label>').join('')+'</div></details>';}
function settlementProfileFields(v){return '<div class="form-section"><h3>结算档案</h3><div class="fieldgrid"><label>微信昵称 / 联系人<input id="vendor-wechat" maxlength="100" value="'+esc(v.wechat||'')+'"></label><label>结算邮箱<input id="vendor-settlement-email" type="email" value="'+esc(v.settlementEmail||'')+'" placeholder="billing@example.invalid"></label><label>币安 ID（文本）<input id="vendor-binance-id" maxlength="100" value="'+esc(v.binanceId||'')+'" placeholder="DEMO-800001"></label><label>合同计价系数（CNY / 消耗 USD）<input id="vendor-coefficient" type="number" min="0.000001" step="0.000001" value="'+esc(v.coefficient||'1.8')+'"></label></div><p class="muted small">此系数用于后续结算，与账号统计倍率分开。修改不重算已生成结算单；原型只填写虚构资料。</p>'+groupCoefficientFields(v)+'</div>';}
function readSettlementProfile(){return {wechat:$('vendor-wechat').value.trim(),settlementEmail:$('vendor-settlement-email').value.trim(),binanceId:$('vendor-binance-id').value.trim(),coefficient:$('vendor-coefficient').value,groupCoefficients:Object.fromEntries([...document.querySelectorAll('[data-group-coefficient]')].filter(e=>e.value.trim()).map(e=>[e.dataset.groupCoefficient,e.value]))};}
function validateSettlementProfile(b){if(!b.wechat||!/^[^@\s]+@example\.invalid$/.test(b.settlementEmail)||!/^DEMO-[A-Za-z0-9-]+$/.test(b.binanceId))return '请补齐演示联系人、@example.invalid 结算邮箱和 DEMO- 开头的币安 ID';try{for(const c of [b.coefficient,...Object.values(b.groupCoefficients)])settlementCents(10000,c,'1');}catch(e){return e.message;}return '';}
