function editAdminProxy(id){openProxyEditor(id);}

document.addEventListener('change',event=>{
 const t=event.target;if(t.dataset.adminFilter){adminFilters[t.dataset.adminFilter]=t.value;if(t.dataset.adminFilter==='vendor')adminFilters.account='all';adminPages[adminView]=1;renderAdmin();}
 if(t.id==='settlement-state'){settlementFilter=t.value;adminPages.settlements=1;renderAdmin();}
 if(t.hasAttribute('data-settlement-input')){settlementPreview=null;$('settlement-save').disabled=true;$('settlement-preview').innerHTML='';$('settlement-error').textContent='参数已变更，请重新预览。';}
});
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b||b.disabled)return;const action=b.dataset.action,id=Number(b.dataset.id);
 if(action==='portal-login'){if($('portal-email').value.trim()!=='vendor-a@example.invalid'){$('portal-login-error').textContent='原型仅开放演示供应商 A，请使用显示的演示邮箱。';return;}portalLoggedIn=true;page='accounts';previewRole='vendor';render();}
 if(action==='portal-logout'){portalLoggedIn=false;$('modal').close();render();}
 if(action==='statement-detail')statementDetail(id);
 if(action==='statement-export')exportStatement(id);
 if(action==='scoped-edit'){if(previewRole==='super_admin')editAdminAccount(id);else if(accounts.some(a=>a.id===id))startAccountForm(id,true);}
 const adminActions=['admin-page','admin-dates','admin-range-all','admin-filter-reset','admin-dimension','admin-drill-vendor','admin-usage-detail','admin-export-usage','admin-account-edit','admin-account-save','admin-proxy-detail','admin-proxy-edit','settlement-new','settlement-preview','settlement-save','statement-lock','statement-void-open','statement-void','payment-open','payment-save','group-preview','group-preview-run','portal-settings','portal-save'];
 if(!adminActions.includes(action))return;if(!requireSuperAdmin())return;
 if(action==='admin-page'){adminPages[adminView]=(adminPages[adminView]||1)+Number(b.dataset.delta);renderAdmin();}
 if(action==='admin-dates'){const start=$('admin-start').value,end=$('admin-end').value;if(!start||!end||start>end||end>DEMO_TODAY){adminError='请选择有效日期范围，结束不能晚于演示今日。';}else{adminFilters.start=start;adminFilters.end=end;adminPages[adminView]=1;adminError='';}renderAdmin();}
 if(action==='admin-range-all'){adminFilters.start='2026-09-01';adminFilters.end=DEMO_TODAY;adminPages[adminView]=1;adminError='';renderAdmin();}
 if(action==='admin-filter-reset'){adminFilters=defaultAdminFilters();adminPages[adminView]=1;adminError='';renderAdmin();}
 if(action==='admin-dimension'){adminFilters.dimension=b.dataset.value;adminPages.usage=1;renderAdmin();}
 if(action==='admin-drill-vendor'){adminFilters.vendor=String(id);adminFilters.account='all';adminFilters.dimension='account';adminView='usage';adminPages.usage=1;renderAdmin();}
 if(action==='admin-usage-detail')showUsageDetail(id);
 if(action==='admin-export-usage')exportAdminUsage();
 if(action==='admin-account-edit')editAdminAccount(id);
 if(action==='admin-account-save'){const a=findAccount(id),v=accountVendor(a),name=$('admin-account-name').value.trim(),groups=[...document.querySelectorAll('[name=admin-account-group]:checked')].map(x=>x.value),proxy=Number($('admin-account-proxy').value);if(!name||!groups.length||!selectableProxies(v.id,a.proxy).some(p=>p.id===proxy)){$('admin-account-error').textContent='请填写名称、选择至少一个授权分组及自己的代理。';return;}Object.assign(a,{name,groups,proxy,notes:$('admin-account-notes').value.trim()});auditVendor(v,'修改供应商账号资料','#'+id+' · 授权/暂停/历史保持');$('modal').close();renderAdmin();notify('资料已保存，原授权保留。');}
 if(action==='admin-proxy-detail')showProxyDetail(id);
 if(action==='admin-proxy-edit')editAdminProxy(id);

 if(action==='settlement-new')openSettlementDraft();
 if(action==='settlement-preview')previewSettlement();
 if(action==='settlement-save')saveSettlementDraft();
 if(action==='statement-lock'){const s=settlements.find(x=>x.id===id);if(s.state!=='draft'||s.end>=DEMO_TODAY){$('statement-error').textContent='状态已变化或账期未闭合，不能锁账。';return;}s.state='locked';auditVendor(vendors.find(v=>v.id===s.vendor),'确认锁账',s.number+' · 金额/收款档案/系数已固化');renderAdmin();statementDetail(id);}
 if(action==='statement-void-open'){const s=settlements.find(x=>x.id===id);openModal('作废结算单',s.number,'<div class="notice">仅未付款的草稿或待付款单可作废；释放用量占用，保留本单与审计历史。</div><label>作废原因<textarea id="void-reason" rows="3" maxlength="200"></textarea></label><p id="void-error" class="form-error"></p>','<button data-action="dismiss">取消</button>'+actionButton('statement-void','确认作废',id,'danger'));}
 if(action==='statement-void'){const s=settlements.find(x=>x.id===id),reason=$('void-reason').value.trim();if(!reason||!['draft','locked'].includes(s.state)||paidCents(s)){$('void-error').textContent='请填写原因；已有付款的账单不能作废。';return;}s.state='void';s.voidReason=reason;auditVendor(vendors.find(v=>v.id===s.vendor),'作废结算单',s.number+' · '+reason);$('modal').close();renderAdmin();}
 if(action==='payment-open')openPayment(id);
 if(action==='payment-save')savePayment(id);
 if(action==='group-preview')openGroupPreview(b.dataset.group);
 if(action==='group-preview-run'){const allowed=$('key-entitlement').value==='allowed',rows=allAccounts().filter(a=>!a.archived&&a.groups.includes(b.dataset.group)&&status(a)==='正常');$('key-access-result').innerHTML='<div class="notice '+(allowed?'':'danger-note')+'">'+(allowed?'可消费该分组 · '+rows.length+' 个供应商账号可参与原生调度。创建者角色不会增加供应商管理权限。':'拒绝消费：Key 所属用户未取得分组资格；即使创建者是超级管理员也不能跳过此用户的资格检查。')+'</div>';}
 if(action==='portal-settings')openPortalSettings();
 if(action==='portal-save'){try{const value=$('portal-origin').value.trim(),url=new URL(value);if(url.protocol!=='https:'||!url.hostname.endsWith('.example.invalid')||url.pathname!=='/'||url.search||url.hash||url.username||url.password||url.port||url.origin===portalConfig.adminOrigin)throw new Error();portalConfig.origin=url.origin;auditVendor(ownerPolicy(),'修改独立入口演示配置','Origin 已更新；未部署 DNS/TLS');$('modal').close();notify('演示配置已保存；供应商入口需正式部署后生效。');}catch{$('portal-error').textContent='请填写不同于后台的 https://子域名.example.invalid Origin，不带路径、端口或参数。';}}
});

